INSERT INTO public.featured_promotions (id,kind,title,body,media_url,cta_label,cta_href,sort_order,is_active) VALUES ('promo-event-launch','EVENT','Evento de Lanzamiento activo','Arranca AI-GI-OH: el Evento de Lanzamiento ya está aquí. Juega, consigue Fragmentos y canjéalos por cartas exclusivas antes de que termine.','/assets/bgs/bg-tech.webp','Jugar ahora','/hub','1','t'), ('promo-maintenance','MAINTENANCE','Mantenimiento programado','Habrá una breve ventana de mantenimiento esta semana para mejorar el rendimiento del multijugador. Avisaremos del horario exacto.',NULL,NULL,NULL,'6','t'), ('promo-market','PACK','Nuevos sobres en el Mercado','Abre sobres para ampliar tu colección y reforzar tu mazo.','/assets/renders/python.webp','Ir al Mercado','/hub/market','2','t'), ('promo-multiplayer','NEWS','Demuestra quién manda','Gana combates multijugador, sube tu ELO y completa misiones semanales.',NULL,'Multijugador','/hub/multiplayer','3','t'), ('promo-new-cards','CARD','Nuevas cartas en circulación','Se han añadido nuevas entidades y trampas al catálogo. Búscalas en el mercado y en los sobres.','/assets/renders/flutter.webp','Ver mercado','/hub/market','4','t'), ('promo-story-chapter','STORY','Nuevo capítulo de la historia','BigLog ha desbloqueado un nuevo tramo del mapa Story. Nuevos rivales te esperan.','/assets/story/opponents/opp-ch1-biglog/intro-BigLog.webp','Ir a Story','/hub/story','5','t'), ('promo-system-incident','SYSTEM','Incidencia resuelta','Detectamos y corregimos un fallo que impedía sumar puntos al comprar sobres. Ya está solucionado. ¡Gracias por avisar!',NULL,NULL,NULL,'7','t') ON CONFLICT (id) DO UPDATE SET kind=excluded.kind,title=excluded.title,body=excluded.body,media_url=excluded.media_url,cta_label=excluded.cta_label,cta_href=excluded.cta_href,sort_order=excluded.sort_order,is_active=excluded.is_active;

